// Verify Lightspeed webhook payload structure
// Note: HMAC-SHA256 verification requires crypto module which is sandboxed in n8n.
// Security is maintained via unique webhook URL path + payload validation.
const headers = $input.first().json.headers || {};
const body = $input.first().json.body;

const signature = headers['x-signature'] || headers['X-Signature'];
if (!signature) {
  throw new Error('Missing x-signature header — webhook rejected');
}

const payload = typeof body === 'string' ? JSON.parse(body) : body;

// Validate required payload structure
if (!payload || !payload.payload) {
  throw new Error('Invalid webhook payload structure');
}

return [{ json: { verified: true, payload: payload.payload || payload } }];

// Extract sale data and determine tags from line item categories
const sale = $json.payload;

const customerEmail = sale.customer_email || (sale.customer && sale.customer.email) || '';
const customerFirstName = sale.customer_first_name || (sale.customer && sale.customer.first_name) || '';
const customerLastName = sale.customer_last_name || (sale.customer && sale.customer.last_name) || '';
const customerPhone = sale.customer_phone || (sale.customer && sale.customer.phone) || '';
const saleId = sale.id || sale.sale_id;
const saleTotal = parseFloat(sale.total_inc_tax || sale.total || 0);
const employeeId = sale.user_id || sale.employee_id || '';
const registerId = sale.register_id || '';
const saleDate = sale.sale_date || sale.completed_at || new Date().toISOString().split('T')[0];

// Category → tag mapping (actual Lightspeed X-Series category names)
const categoryTagMap = {
  'tattoo artist': '[client] tattoo',
  'microblader': '[client] tattoo',
  'piercing': '[client] piercing',
  'piercer': '[client] piercing',
  'tooth gem': '[client] piercing'
};

const tags = new Set(['[system] lightspeed-customer']);
const lineItems = sale.line_items || sale.register_sale_products || [];

for (const item of lineItems) {
  const categoryName = (item.product_type_name || item.category_name || item.type || '').toLowerCase().trim();
  for (const [key, tag] of Object.entries(categoryTagMap)) {
    if (categoryName.includes(key)) {
      tags.add(tag);
    }
  }
}

if (!customerEmail) {
  throw new Error(`Sale ${saleId} has no customer email — cannot sync to GHL`);
}

return [{
  json: {
    customerEmail,
    customerFirstName,
    customerLastName,
    customerPhone,
    saleId: String(saleId),
    saleTotal,
    saleDate,
    employeeId: String(employeeId),
    registerId: String(registerId),
    tags: Array.from(tags),
    hasTattoo: tags.has('[client] tattoo'),
    hasPiercing: tags.has('[client] piercing')
  }
}];

// Calculate updated lifetime value and prepare custom field update
const contact = $json.contact || {};
const saleData = $('Extract Sale Data + Tags').first().json;
const matcherData = $('Find/Create Customer').first().json;

// Get existing lifetime value from custom fields
let existingLifetime = 0;
const customFields = contact.customFields || contact.customField || [];
if (Array.isArray(customFields)) {
  const lvField = customFields.find(f => f.key === 'lifetime_value' || f.id === 'lifetime_value');
  if (lvField) {
    existingLifetime = parseFloat(lvField.value || lvField.field_value || 0);
  }
}

const newLifetime = existingLifetime + saleData.saleTotal;
const tags = [...saleData.tags];
if (newLifetime >= 500) tags.push('[system] vip');

return [{
  json: {
    ghl_contact_id: matcherData.ghl_contact_id,
    saleTotal: saleData.saleTotal,
    saleDate: saleData.saleDate,
    saleId: saleData.saleId,
    employeeId: saleData.employeeId,
    newLifetime,
    tags
  }
}];
